import{_ as e,o,c as a,a2 as s}from"./chunks/framework.Dhf_H6O0.js";const n="/mbit-mcpo-proxy-download/guide/images/container-logs.png",g=JSON.parse('{"title":"Reading Logs","description":"","frontmatter":{},"headers":[],"relativePath":"using-the-app/logs.md","filePath":"using-the-app/logs.md"}'),r={name:"using-the-app/logs.md"};function i(l,t,h,c,d,u){return o(),a("div",null,[...t[0]||(t[0]=[s('<h1 id="reading-logs" tabindex="-1">Reading Logs <a class="header-anchor" href="#reading-logs" aria-label="Permalink to &quot;Reading Logs&quot;">​</a></h1><p>The Logs page shows the output from the gateway Docker container. This is where you look when something isn&#39;t working as expected.</p><h2 id="viewing-logs" tabindex="-1">Viewing logs <a class="header-anchor" href="#viewing-logs" aria-label="Permalink to &quot;Viewing logs&quot;">​</a></h2><p>Click <strong>Logs</strong> in the sidebar.</p><p><img src="'+n+`" alt="Container Logs page"></p><p>The log output shows the most recent lines from the container&#39;s stdout and stderr. You&#39;ll see:</p><ul><li><strong>Startup messages</strong> — which servers the gateway connects to and their status</li><li><strong>HTTP requests</strong> — incoming requests from your AI tools</li><li><strong>Connection confirmations</strong> — e.g., <code>Successfully connected to &#39;telecontext&#39;</code></li><li><strong>Errors</strong> — connection failures, auth issues, or server crashes</li></ul><h2 id="controls" tabindex="-1">Controls <a class="header-anchor" href="#controls" aria-label="Permalink to &quot;Controls&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Button</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Refresh</strong></td><td>Fetches the latest logs from the container</td></tr><tr><td><strong>Auto-refresh</strong></td><td>When checked, automatically refreshes the logs every 5 seconds</td></tr></tbody></table><h2 id="what-to-look-for" tabindex="-1">What to look for <a class="header-anchor" href="#what-to-look-for" aria-label="Permalink to &quot;What to look for&quot;">​</a></h2><h3 id="successful-startup" tabindex="-1">Successful startup <a class="header-anchor" href="#successful-startup" aria-label="Permalink to &quot;Successful startup&quot;">​</a></h3><p>After starting the gateway, you should see lines like:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Server Startup Summary</span></span>
<span class="line"><span>Successfully connected to:</span></span>
<span class="line"><span>  - telecontext</span></span></code></pre></div><h3 id="oauth-flow" tabindex="-1">OAuth flow <a class="header-anchor" href="#oauth-flow" aria-label="Permalink to &quot;OAuth flow&quot;">​</a></h3><p>When a server requires OAuth (like Telecontext), you&#39;ll see a line containing an authorization URL. MCPBehindIT detects this and shows an <a href="#oauth-notifications">OAuth toast notification</a> so you can sign in.</p><h3 id="common-errors" tabindex="-1">Common errors <a class="header-anchor" href="#common-errors" aria-label="Permalink to &quot;Common errors&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Log message</th><th>Meaning</th><th>What to do</th></tr></thead><tbody><tr><td><code>Connection refused</code></td><td>The server endpoint is unreachable</td><td>Check the URL in your server definition</td></tr><tr><td><code>401 Unauthorized</code></td><td>Authentication failed</td><td>Re-check your credentials or re-authenticate OAuth</td></tr><tr><td><code>405 Method Not Allowed</code></td><td>Server doesn&#39;t support the expected transport</td><td>Verify you chose the right transport type</td></tr><tr><td><code>stream disconnected, reconnecting</code></td><td>Temporary connection loss</td><td>Usually resolves automatically; check your network</td></tr></tbody></table><h2 id="oauth-notifications" tabindex="-1">OAuth notifications <a class="header-anchor" href="#oauth-notifications" aria-label="Permalink to &quot;OAuth notifications {#oauth-notifications}&quot;">​</a></h2><p>When the gateway detects an OAuth authorization URL in the logs, a notification toast appears at the bottom-right of the app window:</p><ul><li><strong>Title:</strong> &quot;OAuth sign-in required&quot;</li><li><strong>Open in browser</strong> — opens the sign-in page in your default browser</li><li><strong>Copy URL</strong> — copies the URL to your clipboard in case the browser didn&#39;t open</li></ul><p>The toast dismisses automatically after 90 seconds, or you can close it manually.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>If you see the OAuth toast but the browser didn&#39;t open, click <strong>Copy URL</strong> and paste it into your browser manually. This can happen on some macOS security configurations.</p></div>`,22)])])}const f=e(r,[["render",i]]);export{g as __pageData,f as default};
